import { describe, it } from "vitest";

// Quote premiums below are final premiums for a newcomer's (0 years) first
// quote unless stated: policy base + item surcharges + 10 % first insurance
// on the policy base, + 5 G fee, rounded up.
describe("claim office quote", () => {
  it.todo("empty item list -> premium 5 (fee only)");
  it.todo("plain sword (base 100) -> premium 115");
  it.todo("plain amulet (base 60) -> premium 71");
  it.todo("plain staff (base 80) -> premium 93");
  it.todo("plain potion (base 40) -> premium 49");
  it.todo("single moonstone (base 25) -> premium 33 (32.5 rounded up)");
  it.todo("2 runes (base 50) -> premium 60");
  it.todo("3 runes form a block (base 60) -> premium 71");
  it.todo("4 runes get no block (base 100) -> premium 115");
  it.todo("7 runes (base 175) -> premium 198 (197.5 rounded up in MHPCO's favor)");
  it.todo("2 runes + 1 moonstone are not alike (base 75) -> premium 88");
  it.todo("3 runes + 3 moonstones form two blocks (base 120) -> premium 137");
  it.todo("cursed steel sword enchantment 3, newcomer -> premium 165");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge -> premium 115");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge -> premium 145");
  it.todo("cursed sword with enchantment 5 -> both surcharges -> premium 195");
  it.todo("cursed sword + plain amulet -> curse applies to the sword only (210 before policy modifiers) -> premium 231");
  it.todo("customer with 1 year -> no loyalty discount on a sword -> premium 115");
  it.todo("customer with exactly 2 years -> loyalty discount on a sword -> premium 95");
  it.todo("newcomer's second quote for a sword -> 15 % follow-up discount -> premium 100");
  it.todo("3-year customer's second quote for a cursed steel sword enchantment 7 -> premium 160");
});

// Claim payouts: each damage entry is matched to the next not-yet-damaged
// insured item of that type in the policy (in item order).
describe("claim office claim", () => {
  it.todo("regular steel sword enchantment 3, damage 500 -> payout 400, remaining cap 1600");
  it.todo("rune, damage 200 -> payout 100, remaining cap 400");
  it.todo("steel sword enchantment 9, damage 1000 -> payout 400 (50 % clause)");
  it.todo("dragon-material sword enchantment 5, damage 800 -> payout 700 (full reimbursement)");
  it.todo("dragon-material sword enchantment 9, damage 1000 -> payout 400 (50 % rule wins)");
  it.todo("dragon-material sword exactly enchantment 8, damage 1000 -> payout 400");
  it.todo("sword enchantment 9, damage 901 -> payout 350 (350.5 rounded down)");
  it.todo("sword 500 + amulet 300 in one incident -> payout 600 (deductible per item), remaining cap 2600");
  it.todo("two swords both damaged 500 -> payout 800 (own deductible each), remaining cap 3200 (cap 4000)");
  it.todo("cursed sword policy -> cap 2000 from unmodified insurance value: damage 1500 -> payout 1400, remaining cap 600");
  it.todo("sword + 3 runes block -> insurance sum 1750, cap 3500: sword damage 500 -> remaining cap 3100");
  it.todo("sword, two successive claims of 1500 -> payouts 1400 then 600 (reduced to remaining cap), remaining cap 600 then 0");
});

