import { describe, it } from "vitest";

// Rejections are observed as: non-zero exit status, a non-empty error
// description on stderr, and no `results` on stdout.
describe("claim-office CLI", () => {
  it.todo("schema example (5-year customer, silver amulet quote + fire claim 200) -> results [{premium: 59}, {payout: 100, remainingCap: 1100}]");
  it.todo("quote with unknown item type broomstick -> non-zero exit, stderr, no results");
  it.todo("claim damaging an amulet when only a sword is insured -> non-zero exit, stderr");
  it.todo("claim damaging an item of unknown type -> non-zero exit, stderr");
  it.todo("claim with damage amount -200 -> non-zero exit, stderr");
  it.todo("claim with two sword damages but one sword insured -> non-zero exit, whole claim rejected");
});

